arguments.query:
query {
      game(slug: "the-duskbloods") {
        id name slug status developer publisher releaseDate coverUrl backgroundUrl
        studio { id name slug }
        platforms { id name slug }
      }
      games(first: 100, orderBy: "id", orderDir: "asc") {
        nodes { id name slug status studio { id name slug } }
        pageInfo { total hasMore nextOffset }
      }
    }
